import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Coloured-Stone Grading","description":"","frontmatter":{"title":"Coloured-Stone Grading","grading":"colored-stones"},"headers":[],"relativePath":"grading/colored-stones.md","filePath":"grading/colored-stones.md","lastUpdated":1790876393000}'),s={name:"grading/colored-stones.md"};function i(n,e,l,d,c,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="coloured-stone-grading" tabindex="-1">Coloured-Stone Grading <a class="header-anchor" href="#coloured-stone-grading" aria-label="Permalink to &quot;Coloured-Stone Grading&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Coloured gems lack a single 4C scheme. Instead, colour is graded on three axes—hue (position on the colour wheel), tone (lightness), and saturation (intensity). Many laboratories use these descriptive dimensions, but report terms and thresholds can differ.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-colored-stones-en"><p class="gem-identification-boundary__eyebrow">GRADING BOUNDARY</p><h2 id="identification-boundary-colored-stones-en">Boundary &amp; Safety</h2><p>This page describes coloured-gem colour and is not a universal cross-species scorecard. Confirm the species and reporting system before interpreting hue, tone, saturation, or trade terms; colour alone does not prove origin, treatment, or price. </p></aside><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Hue: position on the colour wheel; preferred ranges vary by species and reporting system.</li><li>Tone: lightness; some systems use named bands, but bands and preferred ranges are not universal.</li><li>Saturation: vividness; high saturation is not a universal best condition for every species or market.</li><li>Colour is often important, but cut, clarity, durability, treatment, and supply also affect value.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Grade</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>vivid red, medium tone</td><td>Pigeon-blood red requires species, lab, and context</td></tr><tr><td>emerald</td><td>vivid green, slightly bluish</td><td>Muzo / Chivor may be origin or trade context, not a universal grade</td></tr><tr><td>sapphire</td><td>vivid blue, medium-dark</td><td>Royal / cornflower require a stated report system and scope</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page explains grading descriptions and report terms; the sources document the knowledge basis and do not make this page sufficient for grading, valuing, identifying, or determining the origin of a specific specimen.</p><ul><li><a href="https://www.gia.edu/diamond-quality-factor" target="_blank" rel="noreferrer">GIA: Diamond Quality Factors</a><span>Diamond quality factors including color, clarity, cut, and carat weight; not a price formula</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-clarity/" target="_blank" rel="noreferrer">GIA 4Cs: Diamond Clarity</a><span>Introductory explanation of FL–I3 clarity grades and the 10× observation condition</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors</a><span>Colour, cut, clarity, durability, and market factors vary by gemstone species</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/UK-EN/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>Species-specific context for emerald colour, transparency, inclusions, and treatment</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>Origin opinions use multiple evidence types and may remain inconclusive</span><small>Open source ↗</small></li><li><a href="https://www.ftc.gov/news-events/topics/tools-consumers/jewelry-guides" target="_blank" rel="noreferrer">FTC: Jewelry, Precious Metals, and Pewter Industries Guides</a><span>US consumer and marketing disclosure guidance; not automatically the law of every jurisdiction</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-colored-stones-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-colored-stones-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Hue, tone, and saturation are common descriptive dimensions, but preferred ranges vary by species and reporting system.</span><small>GIA: Colored Gemstone Value Factors; GIA: Emerald Quality Factors</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>Terms such as pigeon-blood, royal, and cornflower require species, laboratory, and market context; they are not universal grades.</span><small>GIA: Colored Gemstone Value Factors</small></li></ul></aside><p><em>See the <a href="./intro.html">grading overview</a>.</em></p>',11)])])}const g=a(s,[["render",i]]);export{p as __pageData,g as default};
